from pathlib import Path
import json, os, time
base=Path.home()/'.local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4'
task='A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2'
out={'task_id':task}
for name,rel in [('state','models/STATE.json'),('continuation','models/CONTINUATION.json')]:
 p=base/rel
 if p.is_file():
  try:o=json.loads(p.read_text(encoding='utf-8'))
  except Exception as e:o={'parse_error':type(e).__name__}
  if isinstance(o,dict): out[name]={k:o.get(k) for k in ('task_id','state','reason','attempt','checkpoint','retry_at','timestamp','next_action')}
res=base/'model_results'/(task+'.json')
out['result_exists']=res.is_file()
if res.is_file():
 try:r=json.loads(res.read_text(encoding='utf-8'))
 except Exception as e:r={'parse_error':type(e).__name__}
 if isinstance(r,dict): out['result']={k:r.get(k) for k in ('task_id','phase','decision','reviewer_model','model','status','completion_sha256','created_at','completed_at')}
runs=base/'runs'
items=[]
if runs.is_dir():
 for p in sorted(runs.glob(task+'-*')):
  files=[]
  try:
   for q in sorted(p.iterdir()):
    if q.is_file(): files.append({'name':q.name,'size':q.stat().st_size,'mtime':q.stat().st_mtime})
  except Exception as e: files=[{'error':type(e).__name__}]
  items.append({'name':p.name,'mtime':p.stat().st_mtime,'files':files})
out['runs']=items[-12:]
print('ERROR_CLASS=R4P2_OVERNIGHT_ASTRA_AUDIT',flush=True)
print('ERROR='+json.dumps(out,separators=(',',':'),sort_keys=True),flush=True)
raise SystemExit(1)
